import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:go_router/go_router.dart';
import 'package:refract/core/margin_models.dart';
import 'package:refract/core/repository.dart';
import 'package:refract/features/margins/margins_page.dart';
import 'package:refract/features/margins/margin_editor_page.dart';
import 'package:refract/features/margins/margin_exchange_page.dart';
import 'package:refract/features/margins/margin_widgets.dart';
String get owner=>List.filled(64,'a').join();
Map<String,dynamic> revision(String id,String text,{bool anchor=false})=>{'id':id,'entry_id':'e','parents':[],'kind':anchor?'highlight':'note','title':'Shared research','body':text,'reply_to':null,'collection_id':null,'done':false,'deleted':false,'anchor':anchor?{'document_id':'doc-$id','quote':'Exact quote $id','prefix':'','suffix':'','heading':null}:null,'source_label':null,'source_url':null,'declared_author':owner,'recorded_ts':100};
MarginWorkspace workspace({String role='owner',bool conflict=false,bool anchored=false})=>MarginWorkspace.fromJson({'id':'w','name':'Private first','owner':owner,'my_key':owner,'role':role,'epoch':2,'local_revision':3,'members':[],'exchange_enabled':false,'pending_transfers':0,'limitations':['Exchange is optional; originals are never synchronized.'],'entries':conflict?[{'id':'e','versions':[revision('r1','Offline one',anchor:anchored),revision('r2','Offline two',anchor:anchored)],'conflict':true,'history_count':3,'resolutions':anchored?{'r1':{'status':'exact','local_item_id':'source-a','block_idx':3,'explanation':'Exact first version.'},'r2':{'status':'relocated','local_item_id':'source-b','block_idx':8,'explanation':'Second version, different source.'}}:{}}]:[]});
class _FakeRepository implements RefractRepository{
 final calls=<String>[];Map<String,dynamic>? published;
 @override dynamic margins(String action,[dynamic payload]){calls.add(action);switch(action){case 'inspect':return {'workspace_id':'w','name':'Selected workspace','owner':owner,'sender':owner,'kind':'invite','epoch':1,'my_role':'viewer','revision_count':0,'entries':[],'members':[],'warning':'Verify the full fingerprint independently; signatures do not verify a person.'};case 'import':return {'workspace_id':'w','explanation':'Imported; further exchange starts paused.'};case 'preview':final p=payload as Map<String,dynamic>;return {'revision':revision('r1',p['body'] as String)..['title']=p['title'],'review_hash':'reviewed-hash'};case 'publish':published=payload as Map<String,dynamic>;return {};default:return true;}}
 @override dynamic noSuchMethod(Invocation i)=>super.noSuchMethod(i);
}
void main(){
 test('Models retain roles, conflicting versions and separate per-version anchor resolutions',(){final w=workspace(role:'viewer',conflict:true,anchored:true);expect(w.canEdit,false);expect(w.enabled,false);expect(w.entries.single.conflict,true);expect(w.entries.single.resolutions['r1']['block_idx'],3);expect(w.entries.single.resolutions['r2']['block_idx'],8);expect(w.entries.single.versions.map((v)=>v.body),['Offline one','Offline two']);});
 testWidgets('Read-only workspace never exposes shared edit actions',(tester)async{await tester.pumpWidget(ProviderScope(overrides:[marginWorkspaceProvider.overrideWith((ref,id)async=>workspace(role:'viewer')),marginPeersProvider.overrideWith((ref,id)async=>[]),marginTransfersProvider.overrideWith((ref,id)async=>[]),marginHistoryProvider.overrideWith((ref,id)async=>{'attribution':'Exporter keys are separate','events':[],'revisions':[]})],child:const MaterialApp(home:MarginWorkspacePage(id:'w'))));await tester.pumpAndSettle();expect(find.text('Add shared content'),findsNothing);expect(find.textContaining('Access: viewer'),findsOneWidget);expect(find.textContaining('Private Reader annotations stay separate'),findsOneWidget);});
 testWidgets('Encrypted import requires inspection and independent fingerprint consent',(tester)async{final fake=_FakeRepository();await tester.pumpWidget(ProviderScope(overrides:[bootstrapProvider.overrideWith((ref)async=>fake)],child:const MaterialApp(home:MarginImportPage())));await tester.enterText(find.widgetWithText(TextField,'Recipient-encrypted package JSON'),'encrypted-test-package');tester.testTextInput.hide();await tester.pumpAndSettle();await tester.ensureVisible(find.text('Decrypt & inspect without merging'));await tester.pumpAndSettle();await tester.tap(find.text('Decrypt & inspect without merging'));await tester.pumpAndSettle();expect(fake.calls,['inspect']);await tester.scrollUntilVisible(find.text('Accept & merge this reviewed package'),160,scrollable:find.byType(Scrollable).first);await tester.pumpAndSettle();expect(find.text('Accept & merge this reviewed package'),findsOneWidget);
 final accept=find.widgetWithText(FilledButton,'Accept & merge this reviewed package');expect(tester.widget<FilledButton>(accept).onPressed,isNull);await tester.ensureVisible(find.widgetWithText(TextField,'Full owner fingerprint independently confirmed'));await tester.pumpAndSettle();await tester.enterText(find.widgetWithText(TextField,'Full owner fingerprint independently confirmed'),owner);tester.testTextInput.hide();await tester.pumpAndSettle();await tester.ensureVisible(find.text('I verified the full owner fingerprint using a trusted channel'));await tester.pumpAndSettle();await tester.tap(find.text('I verified the full owner fingerprint using a trusted channel'));await tester.pumpAndSettle();expect(fake.calls.where((a)=>a=='import'),isEmpty);await tester.ensureVisible(accept);await tester.pumpAndSettle();await tester.tap(accept);await tester.pumpAndSettle();expect(fake.calls.where((a)=>a=='import').length,1);expect(find.text('Open imported workspace'),findsOneWidget);});
 testWidgets('New shared copy is never published before exact preview and explicit confirmation',(tester)async{final fake=_FakeRepository();final router=GoRouter(routes:[GoRoute(path:'/',builder:(context,s)=>Scaffold(body:TextButton(onPressed:()=>context.push('/new'),child:const Text('Original remains private')))),GoRoute(path:'/new',builder:(_,s)=>const MarginNewPage(workspaceId:'w'))]);addTearDown(router.dispose);await tester.pumpWidget(ProviderScope(overrides:[bootstrapProvider.overrideWith((ref)async=>fake),marginWorkspaceProvider.overrideWith((ref,id)async=>workspace())],child:MaterialApp.router(routerConfig:router)));await tester.tap(find.text('Original remains private'));await tester.pumpAndSettle();expect(fake.published,isNull);expect(find.text('Place reviewed copy in workspace'),findsNothing);await tester.enterText(find.widgetWithText(TextField,'Shared entry title'),'Selected note');await tester.enterText(find.widgetWithText(TextField,'Shared note / comment / reference'),'Only reviewed text');tester.testTextInput.hide();await tester.pumpAndSettle();await tester.scrollUntilVisible(find.text('Build exact sharing preview (does not publish)'),160,scrollable:find.byType(Scrollable).first);await tester.pumpAndSettle();await tester.tap(find.text('Build exact sharing preview (does not publish)'));await tester.pumpAndSettle();expect(fake.published,isNull);await tester.scrollUntilVisible(find.text('Place reviewed copy in workspace'),160,scrollable:find.byType(Scrollable).first);await tester.pumpAndSettle();await tester.tap(find.text('Place reviewed copy in workspace'));await tester.pumpAndSettle();expect(fake.published,isNull);await tester.tap(find.text('Cancel'));await tester.pumpAndSettle();await tester.tap(find.text('Place reviewed copy in workspace'));await tester.pumpAndSettle();await tester.tap(find.text('Confirm'));await tester.pumpAndSettle();expect(fake.published?['review_hash'],'reviewed-hash');expect(fake.published?['include_context'],false);expect(fake.published?['share_source_url'],false);expect(find.text('Original remains private'),findsOneWidget);});
 testWidgets('Concurrent versions require explicit review before a resolving edit',(tester)async{await tester.pumpWidget(ProviderScope(overrides:[marginWorkspaceProvider.overrideWith((ref,id)async=>workspace(conflict:true))],child:const MaterialApp(home:MarginEditPage(workspaceId:'w',entryId:'e',revisionId:'r1'))));await tester.pumpAndSettle();expect(find.text('Offline one'),findsWidgets);expect(find.text('Offline two'),findsOneWidget);final save=find.widgetWithText(FilledButton,'Save explicitly reviewed revision');expect(tester.widget<FilledButton>(save).onPressed,isNull);await tester.ensureVisible(find.text('I reviewed all current versions and this explicit selection'));await tester.pumpAndSettle();await tester.tap(find.text('I reviewed all current versions and this explicit selection'));await tester.pumpAndSettle();expect(tester.widget<FilledButton>(save).onPressed,isNotNull);});
 testWidgets('Each conflicting anchor opens its own resolved source, never the first version by accident',(tester)async{final router=GoRouter(routes:[GoRoute(path:'/',builder:(_,s)=>const MarginWorkspacePage(id:'w')),GoRoute(path:'/reader/:id',builder:(_,s)=>Scaffold(body:Text('Source ${s.pathParameters['id']} block ${s.uri.queryParameters['block']}')))]);addTearDown(router.dispose);await tester.pumpWidget(ProviderScope(overrides:[marginWorkspaceProvider.overrideWith((ref,id)async=>workspace(role:'viewer',conflict:true,anchored:true)),marginPeersProvider.overrideWith((ref,id)async=>[]),marginTransfersProvider.overrideWith((ref,id)async=>[]),marginHistoryProvider.overrideWith((ref,id)async=>{'attribution':'Keys','events':[],'revisions':[]})],child:MaterialApp.router(routerConfig:router)));await tester.pumpAndSettle();await tester.ensureVisible(find.text('Open resolved supporting block').last);await tester.pumpAndSettle();await tester.tap(find.text('Open resolved supporting block').last);await tester.pumpAndSettle();expect(find.text('Source source-b block 8'),findsOneWidget);});
 testWidgets('Large encrypted transfers use explicit file export rather than overflowing clipboard IPC',(tester)async{await tester.pumpWidget(MaterialApp(home:Builder(builder:(context)=>Scaffold(body:TextButton(onPressed:()=>marginCode(context,'Large encrypted package',List.filled(260000,'x').join()),child:const Text('Show package'))))));await tester.tap(find.text('Show package'));await tester.pumpAndSettle();expect(find.text('Save package file'),findsOneWidget);expect(tester.widget<ButtonStyleButton>(find.ancestor(of:find.text('Copy complete package'),matching:find.byWidgetPredicate((w)=>w is ButtonStyleButton)).first).onPressed,isNull);});
}
